-- =============================================================================
-- Vomatt API - Flyway baseline: the schema as of 2026-10-27 (spring.jpa.hibernate.ddl-auto=none)
-- Database: PostgreSQL / Schema: vomatt
-- Databases created before Flyway are baselined at this version and skip it; later changes go in V2__*.sql onwards
-- ID: UUID v7, generated by the application's UUIDv7Generator
-- All time columns are TIMESTAMPTZ (mapped to Java OffsetDateTime)
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS vomatt;

-- =============================================================================
-- SEARCH: character bigrams for Poll title + description and usernames (ADR 0001)
-- =============================================================================
CREATE OR REPLACE FUNCTION vomatt.text_bigrams(input TEXT) RETURNS TEXT[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ SELECT COALESCE(array_agg(DISTINCT substr(lower(input), i, 2)), '{}') FROM generate_series(1, char_length(input) - 1) AS i $$;

-- =============================================================================
-- USERS: OTP / OAuth login, no passwords stored; roles stored as text[] (user / moderator / admin)
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.users (
    id               UUID         PRIMARY KEY,
    username         VARCHAR(50)  NOT NULL UNIQUE,
    email            VARCHAR(254) UNIQUE,
    phone_number     VARCHAR(20)  UNIQUE,
    roles            TEXT[]       NOT NULL DEFAULT ARRAY['user'],
    auth_method      VARCHAR(20),
    avatar_url       VARCHAR(500),
    last_login_at    TIMESTAMPTZ,
    points           INTEGER      NOT NULL DEFAULT 0,
    membership_level VARCHAR(20)  NOT NULL DEFAULT 'BASIC',
    active           BOOLEAN      NOT NULL DEFAULT TRUE,
    first_name       VARCHAR(50),
    last_name        VARCHAR(50),
    -- Private by default (visibility key "birthday")
    birthday         DATE,
    location         VARCHAR(100),
    display_name     VARCHAR(100),
    bio              TEXT,
    -- Same bigram search for usernames (user search); not mapped to the entity
    username_bigrams TEXT[]       GENERATED ALWAYS AS (vomatt.text_bigrams(username)) STORED,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT chk_users_identifier CHECK (email IS NOT NULL OR phone_number IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS vomatt.user_preferences (
    id               UUID        PRIMARY KEY,
    user_id          UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    preference_key   VARCHAR(50) NOT NULL,
    preference_value TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, preference_key)
);

-- =============================================================================
-- VOTES
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.votes (
    id                     UUID          PRIMARY KEY,
    title                  VARCHAR(200)  NOT NULL,
    description            VARCHAR(1000),
    creator_id             UUID          NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    vote_type              VARCHAR(20)   NOT NULL DEFAULT 'STANDARD',
    start_time             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    end_time               TIMESTAMPTZ   NOT NULL,
    is_active              BOOLEAN       NOT NULL DEFAULT TRUE,
    allow_multiple_choices BOOLEAN       NOT NULL DEFAULT FALSE,
    is_anonymous           BOOLEAN       NOT NULL DEFAULT FALSE,
    audience               VARCHAR(20)   NOT NULL DEFAULT 'PUBLIC',
    max_choices            INTEGER       NOT NULL DEFAULT 1,
    -- Voter visibility: NOBODY / OWNER (default) / SIGNED_IN; cannot change after the Poll starts
    voter_visibility       VARCHAR(20)   NOT NULL DEFAULT 'OWNER',
    -- Generated bigram column for search; not mapped to the entity
    search_bigrams         TEXT[]        GENERATED ALWAYS AS
                           (vomatt.text_bigrams(COALESCE(title, '') || ' ' || COALESCE(description, ''))) STORED,
    created_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    -- Delete (soft): a Deleted Poll is hidden from everyone, owner included; the row and its Ballots are kept
    deleted_at             TIMESTAMPTZ,
    -- Deadline: the end time the owner set; ending early moves only end_time (ADR 0004)
    deadline               TIMESTAMPTZ   NOT NULL,
    -- Turnout (Participants) for Top: atomically adjusted with option counts, reconciled by db/reconcile-vote-counts.sql
    turnout                INTEGER       NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS vomatt.vote_options (
    id            UUID         PRIMARY KEY,
    text          VARCHAR(200) NOT NULL,
    description   VARCHAR(500),
    vote_id       UUID         NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    display_order INTEGER      NOT NULL DEFAULT 0,
    image_url     VARCHAR(500),
    -- Atomically adjusted when Ballots are written; see db/reconcile-vote-counts.sql to reconcile
    vote_count    INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.user_votes (
    id         UUID        PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id)        ON DELETE CASCADE,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id)        ON DELETE CASCADE,
    -- NULL once an Anonymous Ballot is sealed after the Poll ends (RetentionJob); the count stays in vote_options.vote_count
    option_id  UUID REFERENCES vomatt.vote_options (id) ON DELETE CASCADE,
    -- Anonymous Ballot: left out of the voter list whatever the Poll's Voter Visibility
    anonymous  BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Polls are single-choice: one Ballot row per user per Poll
    UNIQUE (user_id, vote_id)
);

-- Invitees of an Invite-only Poll: only they and the owner can reach it. A row added by ID holds the user; one added
-- by email keeps that normalized email for life and gains the user once the address belongs to an active account
-- (at invite time, or when that email is verified at sign-up / sign-in)
CREATE TABLE IF NOT EXISTS vomatt.vote_invitees (
    id         UUID         PRIMARY KEY,
    vote_id    UUID         NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    user_id    UUID         REFERENCES vomatt.users (id) ON DELETE CASCADE,
    email      VARCHAR(254),
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    UNIQUE (vote_id, user_id),
    CONSTRAINT chk_vote_invitees_user_or_email CHECK (user_id IS NOT NULL OR email IS NOT NULL)
);

-- Addresses a Poll's invitation email went to: sent once per Poll + address, even after the Invitee is removed and re-added
CREATE TABLE IF NOT EXISTS vomatt.vote_invitation_emails (
    vote_id UUID         NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    email   VARCHAR(254) NOT NULL,
    sent_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (vote_id, email)
);

-- Invite Lists: an owner's private, reusable lists for inviting. Inviting an Invite List copies its current members
-- into a Poll's Invitees, so Invite List edits or deletion never touch existing Polls
CREATE TABLE IF NOT EXISTS vomatt.invite_lists (
    id         UUID         PRIMARY KEY,
    owner_id   UUID         NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    name       VARCHAR(50)  NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- Same shape as vote_invitees: a member added by ID holds the user; one added by email keeps that normalized email
-- for life and gains the user once the address belongs to an active account (at add time, or when verified)
CREATE TABLE IF NOT EXISTS vomatt.invite_list_members (
    id             UUID         PRIMARY KEY,
    invite_list_id UUID         NOT NULL REFERENCES vomatt.invite_lists (id) ON DELETE CASCADE,
    user_id        UUID         REFERENCES vomatt.users (id) ON DELETE CASCADE,
    email          VARCHAR(254),
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    UNIQUE (invite_list_id, user_id),
    CONSTRAINT chk_invite_list_members_user_or_email CHECK (user_id IS NOT NULL OR email IS NOT NULL)
);

-- For RANKING / RATING poll types (Phase 2, no entity / service yet)
CREATE TABLE IF NOT EXISTS vomatt.user_rankings (
    id            UUID        PRIMARY KEY,
    user_id       UUID        NOT NULL REFERENCES vomatt.users (id)        ON DELETE CASCADE,
    vote_id       UUID        NOT NULL REFERENCES vomatt.votes (id)        ON DELETE CASCADE,
    option_id     UUID        NOT NULL REFERENCES vomatt.vote_options (id) ON DELETE CASCADE,
    rank_position INTEGER     NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, vote_id, option_id)
);

CREATE TABLE IF NOT EXISTS vomatt.user_ratings (
    id         UUID        PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    score      INTEGER     NOT NULL CHECK (score BETWEEN 1 AND 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, vote_id)
);

-- =============================================================================
-- COMMENTS
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.vote_comments (
    id         UUID        PRIMARY KEY,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    content    TEXT        NOT NULL,
    -- Replies are one level: parent_id only points to top-level comments
    parent_id  UUID        REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE,
    is_deleted BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.comment_likes (
    id         UUID        PRIMARY KEY,
    comment_id UUID        NOT NULL REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id)         ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (comment_id, user_id)
);

-- One report per user per Comment; read only by admins (GET /api/admin/comment-reports)
CREATE TABLE IF NOT EXISTS vomatt.comment_reports (
    id          UUID         PRIMARY KEY,
    comment_id  UUID         NOT NULL REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE,
    reporter_id UUID         NOT NULL REFERENCES vomatt.users (id)         ON DELETE CASCADE,
    reason      VARCHAR(20)  NOT NULL,
    note        VARCHAR(500),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    UNIQUE (comment_id, reporter_id)
);

-- =============================================================================
-- USER BLOCKS: one-way; the blocker no longer sees Polls (public lists) or Comments authored by the blocked user
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.user_blocks (
    id         UUID        PRIMARY KEY,
    blocker_id UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    blocked_id UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (blocker_id, blocked_id),
    CHECK (blocker_id <> blocked_id)
);

-- =============================================================================
-- USER FOLLOWS: one-way; the follower's Following list (GET /api/votes/following) shows Polls the followed user created
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.user_follows (
    id          UUID        PRIMARY KEY,
    follower_id UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    followed_id UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (follower_id, followed_id),
    CHECK (follower_id <> followed_id)
);

-- =============================================================================
-- FEEDBACK: free-text product feedback from signed-in users; read straight from the database
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.feedback (
    id         UUID        PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    content    TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =============================================================================
-- NOTIFICATIONS: derived at read time from the rows they are about; only read state is stored (ADR 0003, ADR 0005).
-- A notification is identified by its kind (NotificationKind) and the id of its source row: the Poll, Invitee row,
-- follow or Comment. source_id has no foreign key, as it points into different tables; a read row whose source is
-- gone names no notification any more and is never matched.
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.notification_reads (
    user_id   UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    kind      VARCHAR(20) NOT NULL,
    source_id UUID        NOT NULL,
    read_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, kind, source_id)
);

-- "Mark all read": every notification created at or before read_at counts as read
CREATE TABLE IF NOT EXISTS vomatt.notification_read_all (
    user_id UUID        PRIMARY KEY REFERENCES vomatt.users (id) ON DELETE CASCADE,
    read_at TIMESTAMPTZ NOT NULL
);

-- =============================================================================
-- TAGS
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.tags (
    id            UUID         PRIMARY KEY,
    name          VARCHAR(30)  NOT NULL UNIQUE,
    slug          VARCHAR(50)  NOT NULL UNIQUE,
    description   VARCHAR(200),
    display_order INTEGER      NOT NULL DEFAULT 0,
    usage_count   INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.vote_tags (
    vote_id UUID NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    tag_id  UUID NOT NULL REFERENCES vomatt.tags (id)  ON DELETE RESTRICT,
    PRIMARY KEY (vote_id, tag_id)
);

-- =============================================================================
-- LOOKUP (dictionary tables)
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.lookup (
    id             UUID         PRIMARY KEY,
    lookup_type    VARCHAR(50)  NOT NULL,
    lookup_key     VARCHAR(50)  NOT NULL,
    lookup_value   JSON         NOT NULL,
    seq            INT          NOT NULL DEFAULT 0,
    parent_type    VARCHAR(50),
    parent_key     VARCHAR(50),
    is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
    description    VARCHAR(100),
    frontend_using BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_lookup_type_key UNIQUE (lookup_type, lookup_key)
);

-- =============================================================================
-- AUDIT_LOGS: no FK on purpose, so audit records survive user deletion
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.audit_logs (
    id            UUID         PRIMARY KEY,
    user_id       VARCHAR(36),
    username      VARCHAR(254),
    action        VARCHAR(50)  NOT NULL,
    resource_type VARCHAR(50)  NOT NULL,
    resource_id   VARCHAR(36),
    ip_address    VARCHAR(45),
    user_agent    TEXT,
    request_uri   VARCHAR(500),
    http_method   VARCHAR(10),
    success       BOOLEAN      NOT NULL DEFAULT TRUE,
    error_message TEXT,
    details       TEXT,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- =============================================================================
-- INDEXES (UNIQUE columns already have an index; not duplicated here)
-- =============================================================================
CREATE INDEX IF NOT EXISTS idx_votes_creator_start_id      ON vomatt.votes (creator_id, start_time DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_votes_start_id              ON vomatt.votes (start_time DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_votes_end_id                ON vomatt.votes (end_time, id);
-- CLOSING_SOON notifications (NotificationRepository): a followed user's Polls ending within the next day
CREATE INDEX IF NOT EXISTS idx_votes_creator_end           ON vomatt.votes (creator_id, end_time);
CREATE INDEX IF NOT EXISTS idx_votes_turnout_start_id      ON vomatt.votes (turnout DESC, start_time DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_votes_search_bigrams        ON vomatt.votes USING GIN (search_bigrams);
CREATE INDEX IF NOT EXISTS idx_users_username_bigrams      ON vomatt.users USING GIN (username_bigrams);
CREATE INDEX IF NOT EXISTS idx_vote_options_vote_order     ON vomatt.vote_options (vote_id, display_order);
CREATE INDEX IF NOT EXISTS idx_user_votes_vote_option      ON vomatt.user_votes (vote_id, option_id);
CREATE INDEX IF NOT EXISTS idx_user_votes_vote_created     ON vomatt.user_votes (vote_id, created_at, id);
-- Option FK: ON DELETE CASCADE from vote_options would otherwise seq-scan user_votes
CREATE INDEX IF NOT EXISTS idx_user_votes_option           ON vomatt.user_votes (option_id);
CREATE INDEX IF NOT EXISTS idx_vote_invitees_user_id       ON vomatt.vote_invitees (user_id);
-- One row per Poll + email; the email index serves binding at sign-up / sign-in
CREATE UNIQUE INDEX IF NOT EXISTS uk_vote_invitees_vote_email ON vomatt.vote_invitees (vote_id, email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_vote_invitees_email         ON vomatt.vote_invitees (email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_invite_lists_owner_id       ON vomatt.invite_lists (owner_id);
CREATE INDEX IF NOT EXISTS idx_invite_list_members_user_id ON vomatt.invite_list_members (user_id);
-- One row per Invite List + email; the email index serves binding at sign-up / sign-in
CREATE UNIQUE INDEX IF NOT EXISTS uk_invite_list_members_list_email ON vomatt.invite_list_members (invite_list_id, email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_invite_list_members_email   ON vomatt.invite_list_members (email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_user_rankings_vote_id       ON vomatt.user_rankings (vote_id);
-- Option FK: ON DELETE CASCADE from vote_options would otherwise seq-scan user_rankings
CREATE INDEX IF NOT EXISTS idx_user_rankings_option        ON vomatt.user_rankings (option_id);
CREATE INDEX IF NOT EXISTS idx_user_ratings_vote_id        ON vomatt.user_ratings (vote_id);
CREATE INDEX IF NOT EXISTS idx_vote_comments_vote_created  ON vomatt.vote_comments (vote_id, created_at) WHERE is_deleted = FALSE;
CREATE INDEX IF NOT EXISTS idx_vote_comments_user_id       ON vomatt.vote_comments (user_id);
CREATE INDEX IF NOT EXISTS idx_vote_comments_parent        ON vomatt.vote_comments (parent_id, created_at, id);
-- Top-level Comment page (VoteCommentRepository.findPageByVoteId): keeps deleted placeholders, so the partial
-- is_deleted index does not apply. Partial on parent_id IS NULL because IS NULL on a middle key column does not let
-- the planner skip the sort for ORDER BY created_at DESC, id DESC
CREATE INDEX IF NOT EXISTS idx_vote_comments_vote_parent_created ON vomatt.vote_comments (vote_id, created_at DESC, id DESC)
    WHERE parent_id IS NULL;
CREATE INDEX IF NOT EXISTS idx_comment_likes_user_id       ON vomatt.comment_likes (user_id);
-- Admin report list, newest first (CommentReportRepository.findPage); reporter FK cascade
CREATE INDEX IF NOT EXISTS idx_comment_reports_created     ON vomatt.comment_reports (created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_comment_reports_reporter    ON vomatt.comment_reports (reporter_id);
-- Blocked-user FK: the UNIQUE (blocker_id, blocked_id) cannot serve ON DELETE CASCADE from the blocked side
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocked         ON vomatt.user_blocks (blocked_id);
-- Block list page (UserBlockRepository.findPage)
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocker_created ON vomatt.user_blocks (blocker_id, created_at DESC, id DESC);
-- Follower list page (UserFollowRepository.findFollowersPage); its leading followed_id also serves ON DELETE CASCADE
-- from the followed side, which the UNIQUE (follower_id, followed_id) cannot
CREATE INDEX IF NOT EXISTS idx_user_follows_followed_created ON vomatt.user_follows (followed_id, created_at DESC, id DESC);
-- Follow list page (UserFollowRepository.findPage)
CREATE INDEX IF NOT EXISTS idx_user_follows_follower_created ON vomatt.user_follows (follower_id, created_at DESC, id DESC);
-- Admin feedback list, newest first (FeedbackRepository.findPage), all users or one; the second also serves the user FK cascade
CREATE INDEX IF NOT EXISTS idx_feedback_created            ON vomatt.feedback (created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_user_created       ON vomatt.feedback (user_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_tags_usage_count            ON vomatt.tags (usage_count DESC);
CREATE INDEX IF NOT EXISTS idx_vote_tags_tag_id            ON vomatt.vote_tags (tag_id);
CREATE INDEX IF NOT EXISTS idx_lookup_type_active          ON vomatt.lookup (lookup_type, is_active);
CREATE INDEX IF NOT EXISTS idx_lookup_parent               ON vomatt.lookup (parent_type, parent_key);
CREATE INDEX IF NOT EXISTS idx_lookup_frontend             ON vomatt.lookup (frontend_using, is_active);
CREATE INDEX IF NOT EXISTS idx_audit_logs_user_id          ON vomatt.audit_logs (user_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_resource         ON vomatt.audit_logs (resource_type, resource_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at       ON vomatt.audit_logs (created_at);

